const PALETTE_KEYS = Object.keys(PALETTES);

/** An object, a state or a stat (a number). New ones are shown to the player until the author hides them. */
function makeItem(name, kind) {
  kind = kind === 'state' || kind === 'stat' ? kind : 'object';
  const it = { id: uid('i_'), name: name || (kind === 'state' ? 'New state' : kind === 'stat' ? 'New number' : 'New object'), kind, show: true };
  if (kind === 'stat') Object.assign(it, { lo: 0, hi: 10, start: 0 });
  return it;
}


/** The kind of an item as one of 'object' | 'state' | 'stat'. */
const kindOf = it => (it && it.kind === 'state' ? 'state' : it && it.kind === 'stat' ? 'stat' : 'object');

/** The virtual condition id meaning "stat `id` is `n` or more". */
const statTest = (id, n) => `t:${id}:${n}`;

/** Splits a "t:<stat>:<n>" id into { stat, n }, or null if it is not one. */
function parseStatTest(id) {
  const m = /^t:([^:]+):(-?\d+)$/.exec(id);
  return m ? { stat: m[1], n: +m[2] } : null;
}


/** A story page with one empty paragraph. */
function makePassage(name) {
  return {
    id: uid('p_'),
    name: name || 'Untitled page',
    heading: '',
    ending: false,
    valence: '',
    todo: false,
    color: '',
    note: '',
    blocks: [makeBlock('')],
    gives: [],
    takes: [],
    adds: {},
    sends: {},
    choices: []
  };
}


/** A new story with a single starting page. */
function makeProject(title) {
  const p = {
    format: 'story-editor',
    version: STORY_VERSION,
    id: uid('s_'),
    title: title || 'Untitled story',
    author: '',
    start: '',
    items: [],
    givens: [],
    passages: [],
    game: cleanGame()
  };
  const first = makePassage('The beginning');
  p.passages.push(first);
  p.start = first.id;
  return p;
}


/**
 * Turns anything that was saved earlier (or edited by hand, or is malformed or
 * hostile) into a clean, safe project. Every value is coerced to the expected
 * type, ids are validated, and references to things that do not exist are dropped.
 * Throws an Error with a friendly message if the data is not a story at all.
 */
/** The story file format this editor writes. A file with an older number is brought up to date by MIGRATIONS; a newer one is opened with a warning. */
const STORY_VERSION = 1;

/**
 * The upgrade chain: MIGRATIONS[n] takes the raw data of a version-n file and returns the raw data of a version n+1 file.
 * Empty while there is only version 1. When the format changes, bump STORY_VERSION, add the step here, and keep an old-format file in
 * qa/fixtures so the story-format test proves it still opens (that test already opens every fixture there).
 */
const MIGRATIONS = {};

/** Set by normalizeProject when it had to change something the author should hear about (shown after opening a file). */
let startFixNote = '';

function normalizeProject(raw) {
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.passages)) {
    throw new Error('This file is not a story backup.');
  }
  const fileVersion = Math.round(Number(raw.version)) || 1;
  for (let v = fileVersion; MIGRATIONS[v]; v++) raw = MIGRATIONS[v](raw); // oldest format first, one step at a time
  const A = x => (Array.isArray(x) ? x : []); // a field of the wrong type (a hand-edited file) counts as empty instead of crashing
  const taken = Object.create(null); // ids already handed out
  const itemMap = Object.create(null); // id as found in the file -> id we use
  const passMap = Object.create(null); // same, for pages

  /* Ids become object keys and are shown in nothing, so they only need to be
     simple and unique. Anything else gets a fresh id. */
  function cleanId(found, prefix, map) {
    let id = String(found === undefined || found === null ? '' : found);
    if (!/^[A-Za-z0-9_\-]{1,64}$/.test(id) || RESERVED_IDS.includes(id) || taken[id]) id = uid(prefix);
    while (taken[id]) id = uid(prefix);
    taken[id] = true;
    if (map && found !== undefined && found !== null && map[String(found)] === undefined) map[String(found)] = id;
    return id;
  }

  const p = {
    format: 'story-editor',
    version: STORY_VERSION,
    id: String(raw.id || uid('s_')).slice(0, 64),
    title: String(raw.title || 'Untitled story'),
    author: String(raw.author || ''),
    start: '',
    items: [],
    givens: [],
    passages: []
  };
  /* the revision counter and the time of the last save to a file (written by Save; display only, the game never reads them) */
  if (raw.rev !== undefined || raw.savedAt !== undefined) {
    const r = Math.round(Number(raw.rev));
    if (Number.isFinite(r) && r > 0) p.rev = Math.min(r, 1e9);
    if (typeof raw.savedAt === 'string' && /^\d{4}-\d\d-\d\dT[\d:.]{5,16}Z$/.test(raw.savedAt)) p.savedAt = raw.savedAt;
  }

  const intIn = (v, lo, hi, d) => {
    v = Math.round(Number(v));
    return Number.isFinite(v) ? Math.max(lo, Math.min(hi, v)) : d;
  };
  A(raw.items).forEach(it => {
    if (!it) return;
    const kind = it.kind === 'state' || it.kind === 'stat' ? it.kind : 'object';
    const clean = {
      id: cleanId(it.id, 'i_', itemMap),
      name: String(it.name || 'Item'),
      kind,
      show: !!it.show
    };
    if (kind === 'stat') {
      clean.lo = intIn(it.lo, STAT_MIN, STAT_MAX - 1, 0);
      clean.hi = intIn(it.hi, clean.lo + 1, Math.min(STAT_MAX, clean.lo + STAT_SPAN), Math.min(STAT_MAX, clean.lo + 10));
      clean.start = intIn(it.start, clean.lo, clean.hi, clean.lo);
    }
    clean._names = Array.isArray(it.names) ? it.names : [];
    p.items.push(clean);
  });
  /* "shown as" names: only for a state or object that exists */
  p.items.forEach(it => {
    const names = it._names
      .map(n => (n && itemMap[String(n.when)] && String(n.name || '').trim() ? { when: itemMap[String(n.when)], name: String(n.name).trim() } : null))
      .filter(Boolean);
    delete it._names;
    if (names.length) it.names = names;
  });

  /* Givens: each answer must be a state, and a state can answer only one Given */
  const answer = Object.create(null);

  const isState = Object.create(null);
  p.items.forEach(it => {
    if (it.kind === 'state') isState[it.id] = true;
  });
  (Array.isArray(raw.givens) ? raw.givens : []).forEach(g => {
    if (!g) return;
    const opts = uniqList(A(g.options).map(id => itemMap[String(id)]).filter(id => id && isState[id] && !answer[id]));
    const gid = cleanId(g.id, 'g_');
    opts.forEach(id => {
      answer[id] = gid;
    });
    p.givens.push({ id: gid, question: String(g.question || 'Who are you?'), options: opts });
  });
  const rawPages = raw.passages.filter(q => q && typeof q === 'object'); // an entry that is not a page (hand-edited file) is skipped
  rawPages.forEach(q => {
    if (q) q._newId = cleanId(q.id, 'p_', passMap);
  });

  /* Keep only ids that exist. Conditions may also name "where things went" (m: ids);
     those are re-validated at the end by pruneVirtual(). */
  function item(id) {
    return itemMap[String(id)];
  }
  const isStat = Object.create(null);
  p.items.forEach(it => {
    if (it.kind === 'stat') isStat[it.id] = true;
  });
  /** A condition list: items, "where it went" ids (checked later by pruneVirtual) and stat tests ("t:<stat>:<n>"). */
  function known(list) {
    return uniqList(
      A(list)
        .map(id => {
          id = String(id);
          if (id.indexOf('m:') === 0) return id;
          if (id.indexOf('t:') === 0) {
            const t = parseStatTest(id);
            const st = t && item(t.stat);
            return st && isStat[st] ? statTest(st, t.n) : null;
          }
          const r = item(id);
          return r && !isStat[r] ? r : null; // a stat is tested with "t:" ids, never on its own
        })
        .filter(Boolean)
    );
  }
  /** Items a page or choice can give or take: real items, but never a stat (stats change by adding) or a Given answer. */
  function knownReal(list) {
    return uniqList(A(list).map(item).filter(id => id && !isStat[id]));
  }
  /** { statId: whole number } of stat changes, dropping zeros and anything that is not a stat. */
  function cleanAdds(o) {
    const out = {};
    if (o && typeof o === 'object')
      Object.keys(o).forEach(k => {
        const id = item(k);
        const d = intIn(o[k], -STAT_SPAN, STAT_SPAN, 0);
        if (id && isStat[id] && d) out[id] = d;
      });
    return out;
  }

  rawPages.forEach(q => {
    if (!q) return;
    const blocks = A(q.blocks).map(b => ({
      text: String((b && b.text) || ''),
      needs: known(b && b.needs),
      forbid: known(b && b.forbid),
      orPrev: !!(b && b.orPrev)
    }));
    if (!blocks.length) blocks.push(makeBlock(''));
    const sends = {};
    if (q.sends && typeof q.sends === 'object') {
      Object.keys(q.sends).forEach(k => {
        if (item(k) && typeof q.sends[k] === 'string') sends[item(k)] = q.sends[k];
      });
    }
    p.passages.push({
      id: q._newId,
      name: String(q.name || 'Untitled page'),
      heading: String(q.heading || ''),
      ending: !!q.ending,
      valence: q.valence === 'good' || q.valence === 'bad' ? q.valence : '',
      todo: !!q.todo,
      color: PAGE_COLORS.includes(q.color) ? q.color : '',
      note: String(q.note || '').slice(0, PAGE_NOTE_MAX),
      blocks,
      gives: knownReal(q.gives).filter(id => !answer[id]), // Givens never change during the story
      takes: knownReal(q.takes).filter(id => !answer[id]),
      adds: cleanAdds(q.adds),
      sends,
      choices: A(q.choices).map(c => {
        const k = c && c.check && typeof c.check === 'object' ? c.check : null;
        const stat = k && item(k.stat);
        return {
          label: String((c && c.label) || ''),
          to: (c && passMap[String(c.to)]) || '',
          needs: known(c && c.needs),
          forbid: known(c && c.forbid),
          gives: knownReal(c && c.gives).filter(id => !answer[id]),
          takes: knownReal(c && c.takes).filter(id => !answer[id]),
          adds: cleanAdds(c && c.adds),
          check: stat && isStat[stat] ? { stat, target: intIn(k.target, -STAT_SPAN, STAT_SPAN + 12, 7), fail: passMap[String(k.fail)] || '' } : null,
          lock: !!(c && c.lock),
          why: String((c && c.why) || '').slice(0, 120)
        };
      })
    });
  });
  if (!p.passages.length) p.passages.push(makePassage('The beginning'));
  p.start = passMap[String(raw.start)] || p.passages[0].id;
  /* the first page can never be an ending: a story that begins by ending is not a story, so such a page becomes a normal one */
  startFixNote = '';
  const sp0 = p.passages.find(q => q.id === p.start);
  if (sp0 && sp0.ending) {
    sp0.ending = false;
    sp0.valence = '';
    startFixNote = `“${sp0.name}” was marked as an ending, but it is where the story starts, and a first page cannot be an ending. It is now a normal page.`;
  }
  if (raw.gameFont === 'system') p.gameFont = 'system';
  p.game = cleanGame(raw.game);
  const langs = cleanLangs(raw.langs);
  if (langs.length) p.langs = langs;
  if (typeof raw.lang0 === 'string' && raw.lang0.trim() && raw.lang0.trim() !== 'English') p.lang0 = raw.lang0.trim().slice(0, LANG_NAME_MAX);
  if (typeof raw.lang0c === 'string' && LANG_CODE.test(raw.lang0c.trim()) && raw.lang0c.trim().toLowerCase() !== 'en') p.lang0c = raw.lang0c.trim();
  pruneVirtual(p);
  if (fileVersion > STORY_VERSION && !startFixNote) startFixNote = `This story was saved by a newer version of the editor (file format ${fileVersion}; this editor reads format ${STORY_VERSION}). It opened, but anything this editor does not know about was left out. Do not save over the original file.`;
  return p;
}


/* ---------------------------------------------------------------------------
   Translations
   ---------------------------------------------------------------------------
   A translation is a table from the exact source text to its translation: project.langs[n].t = { 'Push the door open': 'Empuja la puerta' }.
   Keying by the words (not by a page and position) means moving, reordering or duplicating pages and paragraphs never mixes translations up,
   the same sentence on two pages is translated once, and a sentence that was edited simply shows up as "not translated yet".
   xlStrings lists everything a player can read, each different text once. An exported game carries each language as lists lined up with the
   exported story (xlCompile), and the game's `lang` module swaps the words in when the reader picks a language.
   --------------------------------------------------------------------------- */

const LANG_MAX = 12;

const LANG_NAME_MAX = 40;

const LANG_CODE = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})?$/;

const LANG_TEXT_MAX = 4000;

const LANG_ENTRIES_MAX = 8000;

/** A text as a translation table key: line ends made alike, outer blanks removed. */
const xlNorm = s => String(s === undefined || s === null ? '' : s).replace(/\r\n?/g, '\n').trim();


/** The translation table of a language, checked: text keys and values only, each cut to size. */
function cleanLangs(raw) {
  const out = [];
  const used = {};
  (Array.isArray(raw) ? raw : []).slice(0, LANG_MAX).forEach((L, n) => {
    if (!L || typeof L !== 'object') return;
    let id = String(L.id || '');
    if (!/^[A-Za-z0-9_\-]{1,24}$/.test(id) || used[id]) id = `lg${n + 1}`;
    while (used[id]) id += 'x';
    used[id] = true;
    const t = {};
    let count = 0;
    if (L.t && typeof L.t === 'object' && !Array.isArray(L.t))
      Object.keys(L.t).forEach(k => {
        const v = L.t[k];
        if (typeof v !== 'string' || !v.trim() || !k.trim() || k.length > LANG_TEXT_MAX || count >= LANG_ENTRIES_MAX) return;
        t[xlNorm(k)] = xlNorm(v).slice(0, LANG_TEXT_MAX);
        count++;
      });
    const code = String(L.code || '').trim();
    out.push({ id, name: String(L.name || 'Language').trim().slice(0, LANG_NAME_MAX) || 'Language', code: LANG_CODE.test(code) ? code : '', t });
  });
  return out;
}


/** The reader options, each value checked and every one present (so the editor can read them without guessing). */
function cleanGame(g) {
  g = g && typeof g === 'object' ? g : {};
  const out = {};
  GAME_OPTIONS.forEach(o => {
    const v = g[o.key];
    if (o.kind === 'choice') out[o.key] = o.ok(v) ? v : o.def;
    else out[o.key] = v === undefined ? o.def : o.def ? v !== false : v === true; // a flag that is on by default turns off only when exactly false
  });
  return out;
}


/* ---------------------------------------------------------------------------
   3. The game rules
   ---------------------------------------------------------------------------
   These functions ARE the game. They are copied word for word (with
   Function.prototype.toString) into every exported game, so the editor's Play
   tab and the exported file always behave identically. The list that is copied
   is KL_RULES below, and the checker (section 5) must mirror every one of them:
   contract.mjs, run on every build, plays random stories with these functions
   and with analyze() and fails the build if they ever disagree.
   `flags` is a plain object: { itemId: true } for what the player has or is, and
   { 'v:<statId>': number } for each number (a missing number counts as 0).
   `st` is the numbers' limits, { statId: [lowest, highest, start] } (klStatMap).
   --------------------------------------------------------------------------- */

/**
 * True if the player has or is `id`. A stat test "t:<stat>:<n>" is true when that number is n or more.
 */
function klHas(flags, id) {
  if (id.charCodeAt(0) === 116 && id.charCodeAt(1) === 58) {
    const j = id.lastIndexOf(':');
    return (flags[`v:${id.slice(2, j)}`] || 0) >= +id.slice(j + 1);
  }
  return !!flags[id];
}


/** True if every "needs" item is in `flags` and no "forbid" item is. */
function klCondOk(c, flags) {
  let i;
  const n = c.needs || [];
  const f = c.forbid || [];
  for (i = 0; i < n.length; i++) if (!klHas(flags, n[i])) return false;
  for (i = 0; i < f.length; i++) if (klHas(flags, f[i])) return false;
  return true;
}


/** The paragraphs of page `p` the player sees, honoring conditions and "otherwise" chains. */
function klVisibleBlocks(p, flags) {
  const out = [];
  let chainDone = false;
  let i;
  let b;
  let ok;
  let show;
  const blocks = p.blocks || [];
  for (i = 0; i < blocks.length; i++) {
    b = blocks[i];
    ok = klCondOk(b, flags);
    if (b.orPrev) {
      show = !chainDone && ok;
      if (show) chainDone = true;
    } else {
      show = ok;
      chainDone = ok;
    }
    if (show) out.push(b);
  }
  return out;
}


/** { statId: [lowest, highest, start] } for the stats among a story's items. */
function klStatMap(items) {
  const st = {};
  (items || []).forEach(i => {
    if (i.kind === 'stat') st[i.id] = [i.lo || 0, i.hi === undefined ? 10 : i.hi, i.start || 0];
  });
  return st;
}


/** `flags` with every number at its starting value (given as `st`, see klStatMap). Changes and returns `flags`. */
function klInit(flags, st) {
  for (const id in st) if (st[id][2]) flags[`v:${id}`] = st[id][2];
  return flags;
}


/** Adds each change in `adds` ({ statId: amount }) to `next`, keeping every number inside its limits. Changes `next`. */
function klAdd(next, adds, st) {
  for (const id in adds) {
    const b = st && st[id];
    let v = (next[`v:${id}`] || 0) + adds[id];
    if (b) v = Math.max(b[0], Math.min(b[1], v));
    next[`v:${id}`] = v;
  }
}


/**
 * What the player has or is right after picking choice `c`, before arriving anywhere: what the choice gives is
 * added (forgetting any old "where it went" record for it), what it takes is removed, and its number changes apply.
 */
function klChoose(flags, c, st) {
  const next = {};
  let k;
  let i;
  const g = c.gives || [];
  const t = c.takes || [];
  if (!g.length && !t.length && !c.adds) return flags;
  for (k in flags) if (flags[k]) next[k] = flags[k];
  for (i = 0; i < g.length; i++) {
    for (k in next) if (k.indexOf(`m:${g[i]}:`) === 0) delete next[k];
    next[g[i]] = true;
  }
  for (i = 0; i < t.length; i++) delete next[t[i]];
  if (c.adds) klAdd(next, c.adds, st);
  return next;
}


/** The choices of page `p` the player can use right now. */
function klVisibleChoices(p, flags) {
  return (p.choices || []).filter(c => klCondOk(c, flags));
}


/** The choices of page `p` that appear at all: usable ones, plus locked ones (shown greyed out) that cannot be used yet. */
function klShown(p, flags) {
  return (p.choices || []).filter(c => c.lock || klCondOk(c, flags));
}


/**
 * What the player has or is after arriving on page `p`.
 * Order: what is given here comes back, so any record of where it went is forgotten; an object handed over
 * (or left here) is recorded as such, but only if the player really had it; then what is given is added,
 * what is taken is removed, and the page's number changes apply. A hand-over with no recipient typed is simply a loss.
 */
function klArrive(flags, p, st) {
  const next = {};
  const gives = p.gives || [];
  const takes = p.takes || [];
  const sends = p.sends || {};
  for (const k in flags) if (flags[k]) next[k] = flags[k];
  const forget = id => {
    for (const k in next) if (k.startsWith(`m:${id}:`)) delete next[k];
  };
  for (const id of gives) forget(id);
  for (const id of takes) {
    const d = sends[id];
    const who = typeof d === 'string' && d.startsWith('w:') ? d.slice(2).trim() : '';
    const to = d === 'here' ? `p:${p.id}` : who ? `w:${who}` : '';
    if (to && flags[id]) {
      forget(id);
      next[`m:${id}:${to}`] = true;
    }
  }
  for (const id of gives) next[id] = true;
  for (const id of takes) delete next[id];
  if (p.adds) klAdd(next, p.adds, st);
  return next;
}


/**
 * The page choice `c` leads to. An ordinary choice always goes to `c.to`. A skill check goes there if the dice
 * (`roll`, 2 to 12, two six-sided dice added together) plus the player's number reach the target, otherwise to the fail page.
 */
function klTarget(flags, c, roll) {
  const k = c.check;
  if (!k) return c.to;
  return roll + (flags[`v:${k.stat}`] || 0) >= k.target ? c.to : k.fail;
}


/** The chance (0 to 100, a whole percent) that skill check `k` succeeds for a player with these `flags`. */
function klOdds(flags, k) {
  const need = k.target - (flags[`v:${k.stat}`] || 0); // what two dice must add up to, at least
  if (need <= 2) return 100;
  if (need > 12) return 0;
  const ways = need <= 7 ? 36 - ((need - 2) * (need - 1)) / 2 : ((13 - need) * (14 - need)) / 2; // of the 36 equally likely rolls
  return Math.round((ways * 100) / 36);
}


/* ---------------------------------------------------------------------------
   4. "Where things went"
   ---------------------------------------------------------------------------
   When an object is lost on a page, the author can say where it went:
     sends[objectId] = 'here'          -> left on that page
     sends[objectId] = 'w:<text>'      -> handed to <text>
   The game then remembers it as a derived flag with an id such as
     m:<objectId>:p:<pageId>   or   m:<objectId>:w:<recipient>
   which any "show only if" box can use. These helpers keep that tidy.
   --------------------------------------------------------------------------- */

/** Reads a sends value. Returns { kind:'p' } | { kind:'w', rest:'text' } | null. */
function parseSend(v) {
  if (v === 'here') return { kind: 'p' };
  if (typeof v === 'string' && v.indexOf('w:') === 0) {
    const t = v.slice(2).trim();
    return t ? { kind: 'w', rest: t } : null;
  }
  return null;
}


/** Every "where it went" record that currently exists, with a readable label. */
function virtualRefs(project) {
  const items = {};
  const out = [];
  const seen = {};
  project.items.forEach(i => {
    items[i.id] = i;
  });
  project.passages.forEach(p => {
    (p.takes || []).forEach(id => {
      const it = items[id];
      if (!it || kindOf(it) !== 'object') return;
      const sd = parseSend((p.sends || {})[id]);
      if (!sd) return;
      const vid = `m:${id}:${sd.kind === 'p' ? `p:${p.id}` : `w:${sd.rest}`}`;
      if (seen[vid]) return;
      seen[vid] = true;
      out.push({
        id: vid,
        itemId: id,
        kind: sd.kind,
        pageId: sd.kind === 'p' ? p.id : '',
        label: sd.kind === 'p' ? `${it.name} left on ${p.name || 'Untitled page'}` : `${it.name} handed to ${sd.rest}`
      });
    });
  });
  return out;
}


/**
 * Drops hand-over data, stat changes, skill checks and conditions that point at things that no longer exist
 * (a deleted object, stat or page). Runs after every edit, so the story never holds a dangling reference.
 */
function pruneVirtual(project) {
  const kinds = {};
  const pages = {};
  project.items.forEach(i => {
    kinds[i.id] = kindOf(i);
  });
  project.passages.forEach(p => {
    pages[p.id] = true;
  });
  project.passages.forEach(p => {
    const keep = {};
    Object.keys(p.sends || {}).forEach(id => {
      const v = p.sends[id];
      if (kinds[id] === 'object' && p.takes.includes(id) && (v === 'here' || (typeof v === 'string' && v.indexOf('w:') === 0))) keep[id] = v;
    });
    p.sends = keep;
  });
  const valid = {};
  virtualRefs(project).forEach(v => {
    valid[v.id] = true;
  });
  function clean(list) {
    for (let i = list.length - 1; i >= 0; i--) {
      const id = list[i];
      if (id.indexOf('m:') === 0 ? !valid[id] : id.indexOf('t:') === 0 ? kinds[(parseStatTest(id) || {}).stat] !== 'stat' : false) list.splice(i, 1);
    }
  }
  function cleanAddsOf(o) {
    if (o) Object.keys(o).forEach(k => kinds[k] !== 'stat' && delete o[k]);
  }
  project.passages.forEach(p => {
    cleanAddsOf(p.adds);
    p.blocks.forEach(b => {
      clean(b.needs);
      clean(b.forbid);
    });
    p.choices.forEach(c => {
      clean(c.needs);
      clean(c.forbid);
      cleanAddsOf(c.adds);
      if (c.check) {
        if (kinds[c.check.stat] !== 'stat') c.check = null;
        else if (c.check.fail && !pages[c.check.fail]) c.check.fail = '';
      }
    });
  });
}


/* ============================================================================
   PART 1b · MAP LAYOUT  (pure functions: no page, no DOM; the Map tab draws what these return)
   ----------------------------------------------------------------------------
   A story is a directed graph: pages are nodes, choices are arrows. There is no
   single best picture of a graph; each drawing trades some qualities for others
   (fewer crossing arrows, related pages close together, groups kept apart, a
   picture that stays put while you edit, speed). So the Map offers several
   views, measures each against those qualities, and lets the author choose by task.

     1. mapGraph       what to draw: Given filter, folded runs, merged arrows
     2. mapImportance  choke points (every route to the goal passes there) and traffic
     3. layered        the main engine, a Sugiyama-style layered drawing:
                         layers   = how many choices from the start
                         order    = crossing reduction (barycenter sweeps + adjacent swaps),
                                    seeded with the previous order so the picture stays put
                         place    = least-squares placement under order constraints, solved
                                    exactly per layer by pool-adjacent-violators; long arrows
                                    get invisible waypoints so they run straight through gaps
                         options  = left-to-right or top-down; choke points held on one line
                                    (spine); pages kept inside lanes (Given lanes); box sizes
                                    from flow (river)
     4. arcLayout, matrixLayout, shapeLayout   the other views
     5. playtest       thousands of simulated players picking at random, using the game's
                       own rules: visits, moves between pages, and how runs end
     6. mapMetrics     scores a drawing on crossings, neighborhood preservation, group
                       separation, stability, reading direction, compactness and time
   ============================================================================ */
const MAP_W = 176; // a normal page box, in map units

const MAP_H = 56;


/** True if a player whose Given answers are `as` ({givenId: answerId}) could ever see choice `c`. */
function mapChoiceVisible(project, c, as) {
  for (const g of project.givens || []) {
    const pick = as?.[g.id];
    if (!pick || !g.options.includes(pick)) continue;
    if ((c.needs || []).some(id => id !== pick && g.options.includes(id))) return false;
    if ((c.forbid || []).includes(pick)) return false;
  }
  return true;
}


/** Breadth-first distances from `root` along `outs` (id -> [ids]), never entering `skip`. */
function mapReach(root, outs, skip) {
  const d = { [root]: 0 };
  if (root === skip) return {};
  const q = [root];
  for (let i = 0; i < q.length; i++) {
    for (const w of outs[q[i]] || [])
      if (w !== skip && d[w] === undefined) {
        d[w] = d[q[i]] + 1;
        q.push(w);
      }
  }
  return d;
}


/**
 * Choke points and traffic for the pages `ids` joined by `links` ({from, to}).
 * The goal is the good endings; if there are none yet, the neutral endings; if none, the pages where the
 * story simply stops so far; if none, every ending. A choke point is a page every route from the start to
 * the goal must pass through (the start always is one). Traffic is the share of all routes from the start
 * to any ending or dead end (loops ignored) that pass through a page.
 */
function mapImportance(project, ids, links) {
  const byId = {},
    outs = {},
    isIn = {},
    start = project.start;
  project.passages.forEach(p => {
    byId[p.id] = p;
  });
  ids.forEach(id => {
    isIn[id] = true;
    outs[id] = [];
  });
  links.forEach(l => {
    if (isIn[l.from] && isIn[l.to]) outs[l.from].push(l.to);
  });
  const choke = {},
    traffic = {};
  if (!isIn[start]) return { choke, traffic, goal: [], spine: [] };
  const base = mapReach(start, outs, null),
    reached = ids.filter(id => base[id] !== undefined);
  const pick = f => reached.filter(id => f(byId[id]));
  let goal = pick(p => p.ending && p.valence === 'good');
  if (!goal.length) goal = pick(p => p.ending && !p.valence);
  if (!goal.length) goal = pick(p => !p.ending && !outs[p.id].length);
  if (!goal.length) goal = pick(p => p.ending);
  choke[start] = true;
  for (const v of reached) {
    if (v === start || !goal.length) continue;
    const others = goal.filter(t => t !== v);
    if (!others.length && !goal.includes(v)) continue;
    const r = mapReach(start, outs, v);
    if (others.every(t => r[t] === undefined)) choke[v] = true;
  }
  /* routes: drop arrows that go back into a loop (depth-first), then count paths in what is left */
  const state = { [start]: 1 },
    post = [],
    dag = { [start]: [] },
    stack = [[start, 0]];
  while (stack.length) {
    const top = stack[stack.length - 1],
      v0 = top[0],
      list = outs[v0];
    if (top[1] < list.length) {
      const w = list[top[1]++];
      if (state[w] === 1) continue; // an arrow back into the current route: a loop
      dag[v0].push(w);
      if (!state[w]) {
        state[w] = 1;
        dag[w] = [];
        stack.push([w, 0]);
      }
    } else {
      state[v0] = 2;
      post.push(v0);
      stack.pop();
    }
  }
  const topo = post.slice().reverse(),
    pin = {},
    pout = {};
  let max = 0;
  topo.forEach(v => {
    pin[v] = v === start ? 1 : pin[v] || 0;
    dag[v].forEach(w => {
      pin[w] = (pin[w] || 0) + pin[v];
    });
  });
  post.forEach(v => {
    let s = byId[v].ending || !dag[v].length ? 1 : 0;
    dag[v].forEach(w => {
      s += pout[w] || 0;
    });
    pout[v] = s;
  });
  topo.forEach(v => {
    max = Math.max(max, pin[v] * pout[v]);
  });
  topo.forEach(v => {
    traffic[v] = max ? (pin[v] * pout[v]) / max : 0;
  });
  const spine = Object.keys(choke).sort((a, b) => base[a] - base[b]);
  return { choke, traffic, goal, spine, depth: base };
}


/**
 * Which boxes and arrows to draw. opts: as ({givenId: answerId}), fold (bool), open ({firstPageId: true} for
 * folded runs opened up), merge (bool).
 * Returns { nodes: [{id, pages, run}], edges: [{from, to, srcs: [{pid, ci, label, gated}], gated}],
 *           groupOf: {pageId: nodeId}, runs: [[pageIds]] (every foldable run, folded or open), hidden, imp, links }.
 */
function mapGraph(project, opts = {}) {
  const byId = {},
    as = opts.as || {};
  const filtering = Object.values(as).some(Boolean);
  project.passages.forEach(p => {
    byId[p.id] = p;
  });
  let links = [];
  project.passages.forEach(p =>
    p.choices.forEach((c, ci) => {
      if (byId[c.to] && !p.ending && mapChoiceVisible(project, c, as))
        links.push({ from: p.id, to: c.to, ci, label: c.label, gated: !!(c.needs.length || c.forbid.length) });
      /* a skill check has a second way out: the page for a failed roll */
      if (c.check && byId[c.check.fail] && !p.ending && mapChoiceVisible(project, c, as))
        links.push({ from: p.id, to: c.check.fail, ci, label: `${c.label} (if the roll fails)`, gated: true, fail: true });
    })
  );
  const outs = {};
  links.forEach(l => {
    (outs[l.from] ||= []).push(l.to);
  });
  const reach = byId[project.start] ? mapReach(project.start, outs, null) : {};
  const keep = {};
  let hidden = 0;
  project.passages.forEach(p => {
    if (!filtering || reach[p.id] !== undefined) keep[p.id] = true;
    else hidden++;
  });
  links = links.filter(l => keep[l.from] && keep[l.to]);
  const ids = project.passages.filter(p => keep[p.id]).map(p => p.id);
  const imp = mapImportance(project, ids, links);
  /* runs: u and v join when u's only next page is v and v's only previous page is u (no start, no endings) */
  const succ = {},
    pred = {};
  links.forEach(l => {
    (succ[l.from] ||= new Set()).add(l.to);
    (pred[l.to] ||= new Set()).add(l.from);
  });
  const only = set => (set && set.size === 1 ? [...set][0] : null);
  const chainNext = u => {
    const v = only(succ[u]);
    if (!v || v === u || v === project.start || byId[v].ending || byId[u].ending) return null;
    return only(pred[v]) === u ? v : null;
  };
  const hasPrev = new Set();
  ids.forEach(u => {
    const v = chainNext(u);
    if (v) hasPrev.add(v);
  });
  const runs = [];
  ids.forEach(u => {
    if (hasPrev.has(u) || u === project.start) return;
    const run = [u];
    let v = chainNext(u);
    while (v && !run.includes(v)) {
      run.push(v);
      v = chainNext(v);
    }
    if (run.length >= 2) runs.push(run);
  });
  const runOf = {};
  if (opts.fold)
    runs.forEach(run => {
      if (!opts.open?.[run[0]])
        run.forEach(id => {
          runOf[id] = run;
        });
    });
  const nodes = [],
    groupOf = {};
  ids.forEach(id => {
    const run = runOf[id];
    if (run && run[0] !== id) return;
    const node = run ? { id: `run:${id}`, pages: run.slice(), run: true } : { id, pages: [id], run: false };
    node.pages.forEach(pid => {
      groupOf[pid] = node.id;
    });
    nodes.push(node);
  });
  const edges = [],
    seen = {};
  links.forEach(l => {
    const a = groupOf[l.from],
      b = groupOf[l.to];
    if (a === b && l.from !== l.to) return; // a step inside a folded run
    const src = { pid: l.from, ci: l.ci, label: l.label, gated: l.gated },
      key = `${a}>${b}`;
    if (opts.merge && seen[key]) {
      seen[key].srcs.push(src);
      seen[key].gated &&= l.gated;
      return;
    }
    const e = { from: a, to: b, srcs: [src], gated: l.gated };
    seen[key] = e;
    edges.push(e);
  });
  return { nodes, edges, groupOf, runs, hidden, imp, links };
}


/* ---------------------------------------------------------------------------
   The layered engine
   --------------------------------------------------------------------------- */

/**
 * Least-squares placement of boxes along one line, keeping their order: positions x minimizing
 * Σ w·(x − want)² with each box at least `gap` after the one before (gaps[i] between i and i+1).
 * Exact, by pool-adjacent-violators on the shifted problem. `lo` (optional) is a floor for the first box.
 */
function mapPlaceLine(want, w, gaps, lo) {
  const n = want.length,
    off = new Array(n);
  off[0] = 0;
  for (let i = 1; i < n; i++) off[i] = off[i - 1] + gaps[i - 1];
  const blocks = []; // each: [sum of w·target, sum of w, count]
  for (let i = 0; i < n; i++) {
    blocks.push([w[i] * (want[i] - off[i]), w[i], 1]);
    while (blocks.length > 1) {
      const b = blocks[blocks.length - 1],
        a = blocks[blocks.length - 2];
      if (a[0] / a[1] <= b[0] / b[1]) break;
      blocks.pop();
      a[0] += b[0];
      a[1] += b[1];
      a[2] += b[2];
    }
  }
  const out = new Array(n);
  let i = 0,
    floor = lo === undefined ? -Infinity : lo;
  for (const b of blocks) {
    const v = Math.max(b[0] / b[1], floor);
    for (let k = 0; k < b[2]; k++, i++) out[i] = v + off[i];
    floor = -Infinity;
  }
  if (lo !== undefined && out[0] < lo) {
    const d = lo - out[0];
    for (let k = 0; k < n; k++) out[k] += d;
  }
  for (let k = 1; k < n; k++) if (out[k] < out[k - 1] + gaps[k - 1]) out[k] = out[k - 1] + gaps[k - 1]; // tidy rounding
  return out;
}


/** Crossings between two neighboring layers, given each segment as [position in upper, position in lower]. */
function mapCrossPairs(segs) {
  segs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const n = segs.length;
  if (n < 2) return 0;
  /* A pair crosses when its upper position is larger and its lower position smaller. Counted with a running tally over the lower
     positions (a Fenwick tree), so a story with thousands of choices costs n log n, not n squared; the count is the same. */
  const lows = [...new Set(segs.map(x => x[1]))].sort((x, y) => x - y);
  const idx = new Map(lows.map((v, i) => [v, i + 1]));
  const tree = new Int32Array(lows.length + 2);
  let c = 0,
    done = 0;
  for (let i = 0; i < n; ) {
    let j = i;
    while (j < n && segs[j][0] === segs[i][0]) j++;
    for (let k = i; k < j; k++) {
      let q = 0;
      for (let t = idx.get(segs[k][1]); t > 0; t -= t & -t) q += tree[t];
      c += done - q; // earlier (smaller upper position) segments that end lower down than this one
    }
    for (let k = i; k < j; k++) {
      for (let t = idx.get(segs[k][1]); t < tree.length; t += t & -t) tree[t]++;
      done++;
    }
    i = j;
  }
  return c;
}


/**
 * A layered drawing of graph G (from mapGraph, with n.w / n.h set).
 * opts: dir 'LR' | 'TB'; root (node id); spine (bool: hold choke points on one line);
 *       lane (node -> lane number, for Given lanes); prev ({nodeId: number}, the order last time, to keep
 *       the picture stable); gapLayer, gapNode (spacing).
 * Returns { nodes (with x, y, w, h, layer, loose), edges (with pts: waypoints, kind fwd|back|flat|self),
 *           width, height, order: {nodeId: number}, lanes: [{lane, from, to}], dir }.
 */
function layered(G, opts = {}) {
  const dir = opts.dir || 'LR',
    LR = dir === 'LR';
  const byNode = {},
    outs = {},
    ins = {};
  G.nodes.forEach(n => {
    byNode[n.id] = n;
    outs[n.id] = [];
    ins[n.id] = [];
  });
  G.edges.forEach(e => {
    outs[e.from].push(e.to);
    ins[e.to].push(e.from);
  });
  /* 1. layers: choices from the start; anything not reached is laid out after, from its own first page */
  const layer = {};
  let maxL = 0;
  const bfs = (r, base, loose) => {
    if (layer[r] !== undefined) return;
    layer[r] = base;
    byNode[r].loose = loose;
    const q = [r];
    for (let i = 0; i < q.length; i++)
      for (const w of outs[q[i]])
        if (layer[w] === undefined) {
          layer[w] = layer[q[i]] + 1;
          byNode[w].loose = loose;
          q.push(w);
        }
    q.forEach(id => {
      maxL = Math.max(maxL, layer[id]);
    });
  };
  if (opts.root && byNode[opts.root]) bfs(opts.root, 0, false);
  G.nodes.forEach(n => {
    if (layer[n.id] === undefined && !ins[n.id].some(f => layer[f] === undefined && f !== n.id)) bfs(n.id, maxL + 1, true);
  });
  G.nodes.forEach(n => {
    if (layer[n.id] === undefined) bfs(n.id, maxL + 1, true);
  });
  /* 2. waypoints: an arrow that spans several layers gets one invisible stop per layer it crosses */
  const L = []; // L[k] = list of vertex records in layer k
  const vert = []; // all vertices: real { id, node } and waypoints { dummy: true, edge }
  const addV = (rec, k) => {
    rec.layer = k;
    rec.idx = vert.length;
    vert.push(rec);
    (L[k] ||= []).push(rec);
    return rec;
  };
  G.nodes.forEach(n => {
    n.v = addV({ id: n.id, node: n, dummy: false }, layer[n.id]);
  });
  const links = []; // neighboring-layer links between vertices: [upper vertex, lower vertex, weight]
  G.edges.forEach(e => {
    const a = byNode[e.from],
      b = byNode[e.to],
      la = layer[e.from],
      lb = layer[e.to];
    e.chain = [];
    if (e.from === e.to) {
      e.kind = 'self';
      return;
    }
    if (la === lb) {
      e.kind = 'flat';
      return;
    }
    e.kind = lb > la ? 'fwd' : 'back';
    const lo = Math.min(la, lb),
      hi = Math.max(la, lb);
    let prevV = (lb > la ? a : b).v;
    for (let k = lo + 1; k < hi; k++) {
      const d = addV({ dummy: true, edge: e }, k);
      e.chain.push(d);
      links.push([prevV, d, prevV.dummy ? 8 : 2]);
      prevV = d;
    }
    links.push([prevV, (lb > la ? b : a).v, prevV.dummy ? 2 : 1]);
    if (e.kind === 'back') e.chain.reverse(); // waypoints in the order the arrow travels
  });
  const up = vert.map(() => []),
    down = vert.map(() => []);
  links.forEach(([u, d, w]) => {
    down[u.idx].push([d, w]);
    up[d.idx].push([u, w]);
  });
  /* 3. order inside each layer: start from last time's order (stable) or depth-first order, then reduce crossings */
  const nL = L.length;
  for (let k = 0; k < nL; k++) L[k] ||= [];
  const dfsRank = {};
  let rank = 0;
  const seenD = new Set(),
    visitD = id => {
      if (seenD.has(id)) return;
      seenD.add(id);
      dfsRank[id] = rank++;
      outs[id].forEach(visitD);
    };
  if (opts.root && byNode[opts.root]) visitD(opts.root);
  G.nodes.forEach(n => visitD(n.id));
  const prev = opts.prev || {};
  const laneOf = v => (v.dummy ? (opts.lane ? laneOfEdge(v.edge) : 0) : opts.lane ? opts.lane(v.node) : 0);
  const laneOfEdge = e => Math.min(opts.lane(byNode[e.from]), opts.lane(byNode[e.to]));
  const rn = Math.max(1, rank); // last time's order is a fraction (0-1) within the layer; so is depth-first rank / count
  L.forEach(list =>
    list.forEach(v => {
      v.key = v.dummy ? (dfsRank[v.edge.from] + dfsRank[v.edge.to]) / 2 / rn : (prev[v.id] ?? dfsRank[v.id] / rn);
    })
  );
  L.forEach(list => {
    list.sort((a, b) => laneOf(a) - laneOf(b) || a.key - b.key);
    list.forEach((v, i) => {
      v.pos = i;
    });
  });
  const crossBetween = k => {
    const segs = [];
    L[k].forEach(u => down[u.idx].forEach(([d]) => segs.push([u.pos, d.pos])));
    return mapCrossPairs(segs);
  };
  const totalCross = () => {
    let c = 0;
    for (let k = 0; k + 1 < nL; k++) c += crossBetween(k);
    return c;
  };
  const snapshot = () => L.map(list => list.slice());
  let best = snapshot(),
    bestC = totalCross();
  const sweep = (k, nb) => {
    L[k].forEach(v => {
      const ns = nb[v.idx];
      v.bary = ns.length ? ns.reduce((s, [o]) => s + o.pos, 0) / ns.length : v.pos;
    });
    L[k].sort((a, b) => laneOf(a) - laneOf(b) || a.bary - b.bary || a.pos - b.pos);
    L[k].forEach((v, i) => {
      v.pos = i;
    });
  };
  /** Swaps neighbors in a layer while that removes crossings (and keeps lanes in place). */
  const transpose = k => {
    let improved = true,
      guard = 0;
    while (improved && guard++ < 8) {
      improved = false;
      for (let i = 0; i + 1 < L[k].length; i++) {
        const a = L[k][i],
          b = L[k][i + 1];
        if (laneOf(a) !== laneOf(b)) continue;
        /* Swapping two neighbors changes only the crossings between their own links (every other page stays on the same side of both),
           so those are counted directly instead of recounting the whole map: the same decision, far less work. */
        let before = 0,
          after = 0;
        const tally = (ea, eb) => {
          for (let p = 0; p < ea.length; p++)
            for (let q = 0; q < eb.length; q++) {
              const x = ea[p][0].pos,
                y = eb[q][0].pos;
              if (x > y) before++;
              else if (x < y) after++;
            }
        };
        if (k + 1 < nL) tally(down[a.idx], down[b.idx]);
        if (k > 0) tally(up[a.idx], up[b.idx]);
        if (after < before) {
          a.pos = i + 1;
          b.pos = i;
          L[k][i] = b;
          L[k][i + 1] = a;
          improved = true;
        }
      }
    }
  };
  const big = vert.length > 600; // very large maps: fewer passes, so the map stays quick
  for (let it = 0; it < (big ? 2 : 6) && bestC > 0; it++) {
    for (let k = 1; k < nL; k++) sweep(k, up);
    for (let k = nL - 2; k >= 0; k--) sweep(k, down);
    if (!big) for (let k = 0; k < nL; k++) transpose(k);
    const c = totalCross();
    if (c < bestC) {
      bestC = c;
      best = snapshot();
    }
  }
  best.forEach((list, k) => {
    L[k] = list;
    list.forEach((v, i) => {
      v.pos = i;
    });
  });
  /* 4. place: along each layer, as near as possible to the vertices it links with (least squares, order kept) */
  const across = v => (v.dummy ? 0 : LR ? v.node.h : v.node.w);
  const gapN = opts.gapNode ?? (LR ? 22 : 28),
    gapD = 12;
  const gapOf = (a, b) => (across(a) + across(b)) / 2 + (a.dummy || b.dummy ? gapD : gapN) + (opts.lane && laneOf(a) !== laneOf(b) ? 40 : 0);
  L.forEach(list => {
    let c = 0;
    list.forEach((v, i) => {
      if (i) c += gapOf(list[i - 1], v);
      v.c = c;
    });
  });
  const isChoke = v => !v.dummy && opts.spine && v.node.choke;
  const placeLayer = (list, nb) => {
    if (!list.length) return;
    const want = [],
      wt = [],
      gaps = [];
    list.forEach((v, i) => {
      const ns = nb[v.idx];
      let s = 0,
        sw = 0;
      ns.forEach(([o, w]) => {
        s += o.c * w;
        sw += w;
      });
      if (isChoke(v)) {
        want.push(0);
        wt.push(1000);
      } else {
        want.push(sw ? s / sw : v.c);
        wt.push(sw ? sw + (v.dummy ? 2 : 0) : 0.2);
      }
      if (i) gaps.push(gapOf(list[i - 1], v));
    });
    const xs = mapPlaceLine(want, wt, gaps);
    list.forEach((v, i) => {
      v.c = xs[i];
    });
  };
  const both = vert.map((_, i) => up[i].concat(down[i]));
  for (let it = 0; it < (big ? 3 : 8); it++) {
    for (let k = 1; k < nL; k++) placeLayer(L[k], it % 3 === 2 ? both : up);
    for (let k = nL - 2; k >= 0; k--) placeLayer(L[k], it % 3 === 2 ? both : down);
  }
  /* lanes: shift each lane so it sits in its own band */
  let lanes = [];
  if (opts.lane) {
    const ext = {}; // lane -> [min, max] of positions
    vert.forEach(v => {
      const ln = laneOf(v),
        lo = v.c - across(v) / 2,
        hi = v.c + across(v) / 2;
      ext[ln] = ext[ln] ? [Math.min(ext[ln][0], lo), Math.max(ext[ln][1], hi)] : [lo, hi];
    });
    const order = Object.keys(ext)
        .map(Number)
        .sort((a, b) => a - b),
      shift = {};
    let at = 0;
    order.forEach(ln => {
      shift[ln] = at - ext[ln][0] + 28;
      lanes.push({ lane: ln, from: at, to: at + (ext[ln][1] - ext[ln][0]) + 56 });
      at += ext[ln][1] - ext[ln][0] + 56 + 16;
    });
    vert.forEach(v => {
      v.c += shift[laneOf(v)];
    });
  }
  /* 5. coordinates: layers along the reading direction, positions across it */
  const gapL = opts.gapLayer ?? (LR ? 80 : 64);
  const depthOf = [];
  let at = 0;
  for (let k = 0; k < nL; k++) {
    let m = 0;
    L[k].forEach(v => {
      if (!v.dummy) m = Math.max(m, LR ? v.node.w : v.node.h);
    });
    depthOf[k] = [at, m || 20];
    at += (m || 20) + gapL;
  }
  let minC = Infinity;
  vert.forEach(v => {
    minC = Math.min(minC, v.c - across(v) / 2);
  });
  if (!isFinite(minC)) minC = 0;
  const pad = 20;
  vert.forEach(v => {
    const [d0, dm] = depthOf[v.layer];
    const along = d0 + dm / 2,
      acrossC = v.c - minC;
    if (v.dummy) {
      v.x = LR ? pad + along : pad + acrossC;
      v.y = LR ? pad + acrossC : pad + along;
      return;
    }
    const n = v.node;
    n.layer = v.layer;
    n.x = LR ? pad + along - n.w / 2 : pad + acrossC - n.w / 2;
    n.y = LR ? pad + acrossC - n.h / 2 : pad + along - n.h / 2;
  });
  lanes = lanes.map(l => ({ lane: l.lane, from: pad + l.from - minC, to: pad + l.to - minC }));
  G.edges.forEach(e => {
    e.pts = e.chain.map(v => [v.x, v.y]);
  });
  let W = 0,
    H = 0;
  G.nodes.forEach(n => {
    W = Math.max(W, n.x + n.w);
    H = Math.max(H, n.y + n.h);
  });
  vert.forEach(v => {
    if (v.dummy) {
      W = Math.max(W, v.x);
      H = Math.max(H, v.y);
    }
  });
  if (lanes.length) {
    if (LR) H = Math.max(H, lanes[lanes.length - 1].to);
    else W = Math.max(W, lanes[lanes.length - 1].to);
  }
  const order = {};
  L.forEach(list =>
    list.forEach(v => {
      if (!v.dummy) order[v.id] = (v.pos + 0.5) / list.length;
    })
  );
  const pos = {};
  G.nodes.forEach(n => {
    pos[n.id] = n;
    delete n.v;
  });
  return { kind: 'nodes', dir, nodes: G.nodes, edges: G.edges, pos, order, lanes, width: W + pad + 60, height: H + pad + 30, crossings: bestC };
}


/* ---------------------------------------------------------------------------
   Other views
   --------------------------------------------------------------------------- */

/** Arc diagram: every page on one line in reading order; arcs above for choices forward, below for choices back. */
function arcLayout(G, base) {
  const nodes = G.nodes.slice().sort((a, b) => a.layer - b.layer || (base.order[a.id] ?? 0) - (base.order[b.id] ?? 0));
  const step = 34,
    pad = 40;
  let maxSpan = 1;
  nodes.forEach((n, i) => {
    n.ai = i;
  });
  const pos = {};
  nodes.forEach(n => {
    pos[n.id] = n;
  });
  G.edges.forEach(e => {
    maxSpan = Math.max(maxSpan, Math.abs(pos[e.to].ai - pos[e.from].ai));
  });
  const lift = Math.min((maxSpan * step) / 2, 520),
    y0 = pad + lift;
  nodes.forEach(n => {
    n.cx = pad + n.ai * step;
    n.cy = y0;
  });
  return { kind: 'arc', nodes, edges: G.edges, pos, baseline: y0, width: pad * 2 + nodes.length * step, height: y0 + 190 };
}


/** Matrix: a grid with a row and a column per page; a filled square where a choice leads from row to column. */
function matrixLayout(G, base) {
  const nodes = G.nodes.slice().sort((a, b) => a.layer - b.layer || (base.order[a.id] ?? 0) - (base.order[b.id] ?? 0));
  nodes.forEach((n, i) => {
    n.mi = i;
  });
  const pos = {};
  nodes.forEach(n => {
    pos[n.id] = n;
  });
  const cell = 18,
    head = 150;
  return { kind: 'matrix', nodes, edges: G.edges, pos, cell, head, width: head + nodes.length * cell + 150, height: head + nodes.length * cell + 30 }; // room on the right for the slanted column names
}


/**
 * Story shape: the stretches between choke points, each summarized by its pattern.
 * Every page belongs to the last choke point that every route to it passes through.
 */
function shapeLayout(project, G) {
  const imp = G.imp,
    spine = imp.spine.filter(id => G.groupOf[id] !== undefined);
  const outs = {};
  G.links.forEach(l => {
    (outs[l.from] ||= []).push(l.to);
  });
  const byId = {};
  project.passages.forEach(p => {
    byId[p.id] = p;
  });
  const all = Object.keys(G.groupOf);
  const owner = {};
  spine.forEach((c, i) => {
    const without = mapReach(project.start, outs, c);
    all.forEach(id => {
      if (id !== c && without[id] === undefined && imp.depth[id] !== undefined) owner[id] = i;
    });
  });
  spine.forEach((c, i) => {
    owner[c] = i;
  });
  const segs = spine.map((c, i) => ({ i, from: c, to: spine[i + 1] || null, pages: [], endings: { good: 0, bad: 0, neutral: 0 } }));
  all.forEach(id => {
    if (spine.includes(id)) return;
    const s = segs[owner[id] ?? 0];
    if (!s) return;
    s.pages.push(id);
    const p = byId[id];
    if (p.ending) s.endings[p.valence || 'neutral']++;
  });
  segs.forEach(s => {
    const inside = new Set(s.pages.concat([s.from]));
    const end = s.to;
    /* routes from this choke point to the next, ignoring loops */
    const memo = {},
      onPath = new Set();
    const count = v => {
      if (v === end) return 1;
      if (memo[v] !== undefined) return memo[v];
      if (onPath.has(v)) return 0;
      onPath.add(v);
      let c = 0;
      for (const w of outs[v] || []) if (w === end || (inside.has(w) && w !== s.from)) c += count(w);
      onPath.delete(v);
      return (memo[v] = c);
    };
    s.routes = end ? count(s.from) : 0;
    let loops = false;
    G.links.forEach(l => {
      if (inside.has(l.from) && inside.has(l.to) && (imp.depth[l.to] ?? 0) <= (imp.depth[l.from] ?? 0) && l.to !== end) loops = true;
    });
    s.loops = loops;
    const ends = s.endings.good + s.endings.bad + s.endings.neutral;
    const rest = s.pages.filter(id => !byId[id].ending).length;
    s.pattern = !end
      ? ends
        ? 'The finale'
        : 'Still being written'
      : !rest
        ? 'Straight on'
        : s.routes <= 1
          ? 'A straight road'
          : 'Branch and rejoin';
    if (end && ends) s.pattern += `, with ${ends} ending${ends === 1 ? '' : 's'} off it`;
    if (loops) s.pattern += ', with a loop';
  });
  return { kind: 'shape', segs, spine };
}


/* ---------------------------------------------------------------------------
   Simulated players
   --------------------------------------------------------------------------- */

/**
 * Plays the story `opts.runs` times (default 2,000) with the game's own rules (klVisibleChoices, klChoose,
 * klArrive). Seeded, so the same story and settings always give the same numbers and nothing flickers.
 * opts.mode: how each simulated player picks among the choices they can see:
 *   'random'  any of them, equally likely
 *   'first'   always the first one listed (the author's "main line")
 *   'curious' a choice leading somewhere they have not been yet, if there is one
 * opts.as: {givenId: answerId} to make every player give those answers (others are picked at random).
 * Each run is kept (its pages in order, as numbers, and how it ended), so a choice or page can be followed:
 * see playtestFilter. "stuck" covers dead ends, unfinished choices, and players still wandering after 400 moves.
 * Returns { runs, ids, paths, results, ends, visits, moves, through, outcome }.
 */
function playtest(project, opts = {}) {
  const runs = opts.runs || 2000,
    mode = opts.mode || 'random',
    as = opts.as || {};
  const byId = {},
    index = {};
  project.passages.forEach((p, i) => {
    byId[p.id] = p;
    index[p.id] = i;
  });
  const ids = project.passages.map(p => p.id);
  let seed = 0x9e3779b9;
  const rnd = () => {
    // mulberry32: small, fast, good enough for dice
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const paths = [],
    results = [],
    ends = [];
  const st = klStatMap(project.items);
  /* pacing: what each simulated reader reads (words), how many pages they press through with only one choice in a row, dice rolled */
  const words = [],
    stretch = [],
    rolled = [];
  const countWords = b => {
    const m = String(b.text || '').match(/\S+/g);
    return m ? m.length : 0;
  };
  /* Worked out once per page instead of once per step (a simulated player steps up to 400 times, 2,000 times over). Every shortcut
     below gives exactly what calling the game's rule would, and only applies when that is certain:
       usable  the page's choices that lead somewhere (the game's rules are then asked only about the choices with conditions)
       plain   no choice has a condition, so `usable` is what every player sees, whatever they hold
       steady  no paragraph has a condition, so every player reads the same words (`wordsAll`)
       quiet   arriving changes nothing (nothing given, taken, or counted), so the player holds exactly what they held before
     (klArrive also drops numbers equal to 0; no rule can tell a 0 from a missing number, so skipping it changes no result.) */
  const info = project.passages.map(p => {
    const usable = (p.choices || []).filter(c => byId[c.to] && (!c.check || byId[c.check.fail]));
    const blocks = p.blocks || [];
    const steady = !blocks.some(b => (b.needs && b.needs.length) || (b.forbid && b.forbid.length) || b.orPrev);
    return {
      usable,
      plain: !(p.choices || []).some(c => (c.needs && c.needs.length) || (c.forbid && c.forbid.length)),
      steady,
      wordsAll: steady ? blocks.reduce((n, b) => n + countWords(b), 0) : 0,
      quiet: !(p.gives && p.gives.length) && !(p.takes && p.takes.length) && !(p.adds && Object.keys(p.adds).length)
    };
  });
  const curious = mode === 'curious';
  if (byId[project.start])
    for (let r = 0; r < runs; r++) {
      let flags = klInit({}, st);
      (project.givens || []).forEach(g => {
        if (!g.options.length) return;
        flags[g.options.includes(as[g.id]) ? as[g.id] : g.options[Math.floor(rnd() * g.options.length)]] = true;
      });
      let p = byId[project.start];
      flags = klArrive(flags, p, st);
      const path = [index[p.id]],
        seen = curious ? new Set([p.id]) : null;
      let result = 'stuck',
        w = 0,
        run = 0,
        longest = 0,
        dice = 0;
      for (let step = 0; step < 400; step++) {
        const pi = info[path[path.length - 1]];
        if (pi.steady) w += pi.wordsAll;
        else
          klVisibleBlocks(p, flags).forEach(b => {
            w += countWords(b);
          });
        if (p.ending) {
          result = p.valence || 'neutral';
          break;
        }
        const cs = pi.plain ? pi.usable : pi.usable.filter(c => klCondOk(c, flags));
        if (!cs.length) break;
        run = cs.length === 1 ? run + 1 : 0;
        longest = Math.max(longest, run);
        let c;
        if (mode === 'first') c = cs[0];
        else if (curious) {
          const fresh = cs.filter(x => !seen.has(x.to));
          c = (fresh.length ? fresh : cs)[Math.floor(rnd() * (fresh.length || cs.length))];
        } else c = cs[Math.floor(rnd() * cs.length)];
        let roll = 0;
        if (c.check) {
          roll = Math.floor(rnd() * 6) + Math.floor(rnd() * 6) + 2; // two dice, the same as the game
          dice++;
        }
        const dest = byId[klTarget(flags, c, roll)];
        const chosen = klChoose(flags, c, st);
        flags = info[index[dest.id]].quiet ? chosen : klArrive(chosen, dest, st);
        p = dest;
        path.push(index[p.id]);
        if (curious) seen.add(p.id);
      }
      paths.push(Uint16Array.from(path));
      results.push(result);
      ends.push(p.ending ? p.id : '');
      words.push(w);
      stretch.push(longest);
      rolled.push(dice);
    }
  return { runs: paths.length, ids, paths, results, ends, words, stretch, rolled, ...playtestCount({ ids, paths, results }, null) };
}


/**
 * Totals for the runs in `pick` (an array of run numbers; null for every run): how many players saw each page
 * (once per player), how often each move was taken, and how the players who saw a page ended.
 */
function playtestCount(pt, pick) {
  /* Counted by page number, not by name: the strings (names and "from>to" keys) are made once at the end, in the order they were first
     met, so the totals are exactly what counting by name gives, in less time. */
  const n = pt.ids.length;
  const seenIn = new Int32Array(n);
  const visitsN = new Int32Array(n);
  const throughN = new Int32Array(n * 4);
  const firstSeen = [];
  const moveN = new Map();
  const slot = { good: 0, bad: 1, neutral: 2, stuck: 3 };
  const outcome = { good: 0, bad: 0, neutral: 0, stuck: 0 };
  const list = pick || pt.paths.map((_, i) => i);
  let turn = 0;
  for (const r of list) {
    turn++; // counts every entry of the list, so a run named twice is counted twice, as before
    const path = pt.paths[r],
      result = pt.results[r],
      k = slot[result];
    outcome[result]++;
    for (let i = 0; i < path.length; i++) {
      const at = path[i];
      if (i) {
        const key = path[i - 1] * 65536 + at;
        moveN.set(key, (moveN.get(key) || 0) + 1);
      }
      if (seenIn[at] !== turn) {
        seenIn[at] = turn;
        if (!visitsN[at]) firstSeen.push(at);
        visitsN[at]++;
        throughN[at * 4 + k]++;
      }
    }
  }
  const visits = {},
    moves = {},
    through = {};
  for (const at of firstSeen) {
    const id = pt.ids[at];
    visits[id] = visitsN[at];
    through[id] = { good: throughN[at * 4], bad: throughN[at * 4 + 1], neutral: throughN[at * 4 + 2], stuck: throughN[at * 4 + 3] };
  }
  for (const [key, count] of moveN) moves[`${pt.ids[Math.floor(key / 65536)]}>${pt.ids[key % 65536]}`] = count;
  return { visits, moves, through, outcome, count: list.length };
}


/** The runs that saw page `id` (sel.page) or took the move from sel.from to sel.to. */
function playtestFilter(pt, sel) {
  const a = pt.ids.indexOf(sel.page ?? sel.from),
    b = sel.to ? pt.ids.indexOf(sel.to) : -1,
    out = [];
  pt.paths.forEach((path, r) => {
    for (let i = 0; i < path.length; i++) {
      if (path[i] !== a) continue;
      if (b < 0 || path[i + 1] === b) {
        out.push(r);
        break;
      }
    }
  });
  return out;
}


/* ---------------------------------------------------------------------------
   Scoring a drawing
   --------------------------------------------------------------------------- */

/** Do the segments (a,b) and (c,d) cross? */
function mapSegCross(a, b, c, d) {
  const o = (p, q, r) => Math.sign((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]));
  return o(a, b, c) * o(a, b, d) < 0 && o(c, d, a) * o(c, d, b) < 0;
}


/**
 * Scores layout `L` (nodes with x, y, w, h; edges with pts) on the qualities that compete in graph drawing.
 * Each score is 0-1, higher is better:
 *   crossings   few arrows cross                         (1 / (1 + crossings per arrow))
 *   neighbors  pages linked by a choice sit near each other (k-nearest-neighbor preservation)
 *   groups      pages reached by the same Given answers (or heading to the same kind of ending) sit together
 *   stability   little moved since the last drawing of this view (the author's mental map)
 *   flow        arrows point the reading way (left to right, or down)
 *   compact     the picture's shape suits a wide screen, with little empty space
 *   speed       how quickly it was drawn
 * `cls` maps page box id -> group name; `prevPos` maps id -> [x, y] from last time.
 */
function mapMetrics(L, ms, cls, prevPos, quick) {
  /* Everything below except "stability" depends only on the drawing itself, and a drawing never changes once built (the map keeps it for
     the next visit), so it is worked out once and kept on L. `quick` is for the toolbar chip, which shows only the crossings, the backward
     arrows and the milliseconds: the nearest-neighbor, group and compactness scores are left for the Compare table. */
  const nodes = L.nodes,
    n = nodes.length;
  const center = nd => [nd.cx ?? nd.x + nd.w / 2, nd.cy ?? nd.y + nd.h / 2];
  const C = (L._centers ||= (() => {
    const c = {};
    nodes.forEach(nd => {
      c[nd.id] = center(nd);
    });
    return c;
  })());
  const memo = (L._metrics ||= {});
  /* crossings: each arrow as a polyline through its waypoints */
  const cross = (memo.cross ??= (() => {
    const segs = [];
    L.edges.forEach((e, ei) => {
      if (e.from === e.to) return;
      const pts = [C[e.from]].concat(e.pts || [], [C[e.to]]);
      for (let i = 0; i + 1 < pts.length; i++) segs.push([pts[i], pts[i + 1], ei]);
    });
    let cr = 0;
    if (L.kind === 'arc') {
      const side = e => (L.pos[e.to].ai > L.pos[e.from].ai ? 1 : -1);
      const iv = L.edges
        .filter(e => e.from !== e.to)
        .map(e => [Math.min(L.pos[e.from].ai, L.pos[e.to].ai), Math.max(L.pos[e.from].ai, L.pos[e.to].ai), side(e)]);
      for (let i = 0; i < iv.length; i++)
        for (let j = i + 1; j < iv.length; j++) {
          const [a, b, s] = iv[i],
            [c, d, t] = iv[j];
          if (s === t && ((a < c && c < b && b < d) || (c < a && a < d && d < b))) cr++;
        }
    } else if (L.kind === 'matrix') cr = 0;
    else if (segs.length <= 4000) {
      /* two segments whose bounding boxes do not overlap cannot cross, so most pairs are dismissed with four comparisons */
      const box = segs.map(s => [Math.min(s[0][0], s[1][0]), Math.max(s[0][0], s[1][0]), Math.min(s[0][1], s[1][1]), Math.max(s[0][1], s[1][1])]);
      for (let i = 0; i < segs.length; i++) {
        const bi = box[i];
        for (let j = i + 1; j < segs.length; j++) {
          const bj = box[j];
          if (bi[1] < bj[0] || bj[1] < bi[0] || bi[3] < bj[2] || bj[3] < bi[2]) continue;
          if (segs[i][2] === segs[j][2]) continue;
          if (mapSegCross(segs[i][0], segs[i][1], segs[j][0], segs[j][1])) cr++;
        }
      }
    } else cr = L.crossings ?? 0;
    return cr;
  })());
  const ne = Math.max(1, L.edges.length);
  /* flow: arrows that go the reading way */
  const flow = (memo.flow ??= (() => {
    let f = 0,
      t = 0;
    L.edges.forEach(e => {
      if (e.from === e.to) return;
      const a = C[e.from],
        b = C[e.to],
        d = L.dir === 'TB' ? b[1] - a[1] : b[0] - a[0];
      t++;
      if (d > 0) f++;
    });
    return { fwd: f, fl: t };
  })());
  const { fwd, fl } = flow;
  if (quick) return { scores: null, raw: { crossings: cross, moved: 0, ms, backward: fl - fwd, edges: L.edges.length } };
  const dist = (a, b) => Math.hypot(C[a][0] - C[b][0], C[a][1] - C[b][1]);
  /* neighborhood preservation: of each page's k nearest boxes (k = how many pages it links with), how many it links with */
  const nb = (memo.nb ??= (() => {
    const adj = {};
    L.edges.forEach(e => {
      if (e.from !== e.to) {
        (adj[e.from] ||= new Set()).add(e.to);
        (adj[e.to] ||= new Set()).add(e.from);
      }
    });
    let np = 0,
      npn = 0;
    if (n > 1 && n <= 600)
      nodes.forEach(nd => {
        const k = adj[nd.id]?.size || 0;
        if (!k) return;
        /* the k nearest other boxes, nearest first and, among equal distances, in page order: the same k that sorting all of them and
           taking the first k gives, found by keeping a short sorted list instead of sorting everything */
        const near = [];
        for (const o of nodes) {
          if (o === nd) continue;
          const d = dist(nd.id, o.id);
          if (near.length === k && d >= near[k - 1][0]) continue;
          let at = near.length;
          while (at > 0 && near[at - 1][0] > d) at--;
          near.splice(at, 0, [d, o]);
          if (near.length > k) near.pop();
        }
        np += near.filter(x => adj[nd.id].has(x[1].id)).length / k;
        npn++;
      });
    return { np, npn };
  })());
  /* group separation: share of pages whose nearest box is in the same group */
  const gr = (memo.gr ??= (() => {
    let gs = 0,
      gsn = 0;
    if (cls && n > 1 && n <= 600)
      nodes.forEach(nd => {
        if (!cls[nd.id]) return;
        let best = null,
          bd = Infinity;
        nodes.forEach(o => {
          if (o !== nd && cls[o.id]) {
            const d = dist(nd.id, o.id);
            if (d < bd) {
              bd = d;
              best = o;
            }
          }
        });
        if (best) {
          gs += cls[best.id] === cls[nd.id] ? 1 : 0;
          gsn++;
        }
      });
    return { gs, gsn };
  })());
  const { np, npn } = nb,
    { gs, gsn } = gr;
  /* stability: mean distance moved since last time, compared with a box width */
  let mv = 0,
    mvn = 0;
  if (prevPos)
    nodes.forEach(nd => {
      const p = prevPos[nd.id];
      if (p) {
        mv += Math.hypot(C[nd.id][0] - p[0], C[nd.id][1] - p[1]);
        mvn++;
      }
    });
  /* compact: closeness to a 16:10 picture, times how much of it the boxes fill */
  const W = L.width || 1,
    H = L.height || 1,
    r = W / H,
    target = 1.6;
  let area = 0;
  nodes.forEach(nd => {
    area += (nd.w || 12) * (nd.h || 12);
  });
  const fill = Math.min(1, (area / (W * H)) * 4);
  const grid = L.kind === 'matrix'; // a matrix has no arrows to cross and no reading direction to follow
  const s = {
    crossings: grid ? null : 1 / (1 + cross / ne),
    neighbors: npn ? np / npn : 1,
    groups: gsn ? gs / gsn : null,
    stability: mvn ? Math.max(0, 1 - mv / mvn / MAP_W) : null,
    flow: grid ? null : fl ? fwd / fl : 1,
    compact: (Math.min(r, target) / Math.max(r, target)) * 0.5 + fill * 0.5,
    speed: 1 / (1 + ms / 60)
  };
  return { scores: s, raw: { crossings: cross, moved: mvn ? mv / mvn : 0, ms, backward: fl - fwd, edges: L.edges.length } };
}


/** How much each quality counts for each task (they add up to 1). */
const MAP_TASKS = {
  edit: { label: 'Editing the structure', w: { crossings: 0.3, neighbors: 0.2, stability: 0.2, flow: 0.15, compact: 0.1, speed: 0.05 } },
  beats: { label: 'Studying story beats', w: { flow: 0.3, crossings: 0.25, compact: 0.2, neighbors: 0.1, stability: 0.1, speed: 0.05 } },
  vars: { label: 'Following variables', w: { groups: 0.35, crossings: 0.2, neighbors: 0.2, stability: 0.15, speed: 0.1 } }
};

/** One number for a task: the weighted mean of the scores that apply (a missing score's weight is shared out). */
function mapTaskScore(scores, task) {
  let s = 0,
    w = 0;
  for (const [k, wk] of Object.entries(MAP_TASKS[task].w))
    if (scores[k] !== null && scores[k] !== undefined) {
      s += scores[k] * wk;
      w += wk;
    }
  return w ? s / w : 0;
}


